1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      /* The color is the content here, so keep it; the stroke guarantees the shape */
60	      .circle svg {
61	        forced-color-adjust: none;
62	        color: var(--fg);
63	      }
64	      svg circle {
65	        stroke: CanvasText;
66	        stroke-width: 2;
67	      }
68	    }
69	    body {
70	      min-height: 100vh;
71	      min-height: 100dvh;
72	      display: grid;
73	      place-items: center;
74	      padding: 1rem;
75	      background: var(--bg);
76	      color: var(--text);
77	      font-family: system-ui, -apple-system, sans-serif;
78	    }
79	    main {
80	      width: 100%;
81	      display: flex;
82	      flex-direction: column;
83	      align-items: center;
84	      text-align: center;
85	    }
86	    .circle {
87	      display: block;
88	      width: min(360px, 100%, 60vh);
89	      width: min(360px, 100%, 60dvh);
90	      aspect-ratio: 1;
91	      border: 0;
92	      border-radius: 50%;
93	      background: none;
94	      color: var(--fg);
95	      cursor: pointer;
96	      touch-action: manipulation;
97	      -webkit-tap-highlight-color: transparent;
98	      -webkit-user-select: none;
99	      user-select: none;
100	      -webkit-touch-callout: none;
101	      transition: color 0.4s;
102	      min-height: 48px;
103	      min-width: 48px;
104	    }
105	    .no-transition,
106	    .no-transition svg {
107	      transition: none !important;
108	    }
109	    .circle:focus-visible {
110	      outline: 3px solid currentColor;
111	      outline-offset: 12px;
112	    }
113	    svg {
114	      display: block;
115	      width: 100%;
116	      height: 100%;
117	      overflow: visible;
118	      /* Leave hit testing to the button's rounded box, not the svg's square one */
119	      pointer-events: none;
120	      opacity: 0.85;
121	      filter: var(--drop);
122	      transition: opacity 0.3s;
123	    }
124	    .circle:active svg,
125	    .circle:focus-visible svg {
126	      opacity: 1;
127	    }
128	    @keyframes pulse {
129	      0% {
130	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
131	      }
132	      100% {
133	        filter: var(--drop) drop-shadow(0 0 0 transparent);
134	      }
135	    }
136	    @media (hover: hover) {
137	      .circle:hover svg {
138	        opacity: 1;
139	      }
140	    }
141	    @media (prefers-reduced-motion: no-preference) {
142	      svg {
143	        transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s;
144	      }
145	      .circle:focus-visible svg {
146	        transform: scale(1.05);
147	      }
148	      .circle:active svg {
149	        transform: scale(0.97);
150	      }
151	      .circle.color-changed svg {
152	        animation: pulse 0.5s ease-out;
153	      }
154	    }
155	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
156	      .circle:hover:not(:active) svg {
157	        transform: scale(1.05);
158	      }
159	    }
160	    .visually-hidden {
161	      position: absolute;
162	      width: 1px;
163	      height: 1px;
164	      overflow: hidden;
165	      clip-path: inset(50%);
166	      white-space: nowrap;
167	    }
168	    .status {
169	      margin-top: 2rem;
170	      font-weight: 600;
171	    }
172	    .hint {
173	      margin-top: 0.25rem;
174	      font-size: 0.875rem;
175	      line-height: 1.75;
176	      text-wrap: balance;
177	    }
178	    .help-button {
179	      margin-left: 0.5rem;
180	      display: inline-block;
181	      width: 1.5rem;
182	      height: 1.5rem;
183	      border-radius: 50%;
184	      background: var(--kbd-bg);
185	      border: 1px solid var(--text);
186	      color: var(--text);
187	      cursor: pointer;
188	      font: inherit;
189	      font-size: 0.75rem;
190	      font-weight: bold;
191	      line-height: 1;
192	      text-align: center;
193	      vertical-align: middle;
194	      touch-action: manipulation;
195	      transition: background-color 0.2s, color 0.2s;
196	    }
197	    .help-button:focus-visible {
198	      outline: 2px solid currentColor;
199	      outline-offset: 2px;
200	    }
201	    @media (hover: hover) {
202	      .help-button:hover {
203	        background: var(--text);
204	        color: var(--bg);
205	      }
206	    }
207	    .keys {
208	      display: none;
209	    }
210	    .keys.visible {
211	      display: inline;
212	    }
213	    @media (hover: none) and (pointer: coarse) {
214	      .hint .keys {
215	        display: none !important;
216	      }
217	      .help-button {
218	        display: none;
219	      }
220	    }
221	    kbd {
222	      display: inline-block;
223	      padding: 0.125rem 0.375rem;
224	      background: var(--kbd-bg);
225	      border: 1px solid transparent;
226	      border-radius: 0.25rem;
227	      font-family: monospace;
228	      font-size: 0.75em;
229	      line-height: 1.2;
230	    }
231	  </style>
232	</head>
233	<body>
234	  <main>
235	    <h1 class="visually-hidden">Animated Circle</h1>
236	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
237	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
238	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
239	      </svg>
240	    </button>
241	    <p class="status" id="status" role="status" aria-live="polite">Blue</p>
242	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
243	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
244	  </main>
245	  <script>
246	    const config = {
247	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
248	      storageKey: 'circle-color',
249	      hapticDuration: 50,
250	      longPressDuration: 500,
251	      longPressTolerance: 10,
252	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
253	    };
254	
255	    const DOM = {
256	      button: document.querySelector('.circle'),
257	      status: document.querySelector('.status'),
258	      helpButton: document.querySelector('.help-button'),
259	      keyHint: document.querySelector('.keys'),
260	      verbSpan: document.querySelector('.verb'),
261	      doubleVerbSpan: document.querySelector('.double-verb'),
262	    };
263	
264	    const state = {
265	      index: 0,
266	      shiftHeld: false,
267	      hoverCapable: true,
268	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
269	      hoverQuery: matchMedia('(hover: none)'),
270	      longPressTimer: null,
271	      clickTimer: null,
272	      longPressed: false,
273	      pressX: 0,
274	      pressY: 0,
275	      pointerType: '',
276	    };
277	
278	    function loadColor() {
279	      try {
280	        return localStorage.getItem(config.storageKey);
281	      } catch {
282	        return null;
283	      }
284	    }
285	
286	    function saveColor(color) {
287	      try {
288	        localStorage.setItem(config.storageKey, color);
289	      } catch {}
290	    }
291	
292	    function applyColor() {
293	      const color = config.colors[state.index];
294	      // The first color is the :root default, so it needs no attribute
295	      if (state.index === 0) delete DOM.button.dataset.color;
296	      else DOM.button.dataset.color = color;
297	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
298	    }
299	
300	    function syncFromStorage(color = loadColor()) {
301	      const index = config.colors.indexOf(color);
302	      state.index = index === -1 ? 0 : index;
303	      applyColor();
304	    }
305	
306	    // acknowledge: give feedback even when the color is already the requested one
307	    function setIndex(next, { haptic = false, acknowledge = false } = {}) {
308	      const changed = next !== state.index;
309	      if (!changed && !acknowledge) return;
310	      if (changed) {
311	        state.index = next;
312	        applyColor();
313	        saveColor(config.colors[state.index]);
314	      }
315	
316	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
317	
318	      if (state.reducedMotion.matches) return;
319	      DOM.button.classList.remove('color-changed');
320	      void DOM.button.offsetWidth;
321	      DOM.button.classList.add('color-changed');
322	    }
323	
324	    function changeColor(step) {
325	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
326	    }
327	
328	    function updateDeviceVerbs() {
329	      state.hoverCapable = !state.hoverQuery.matches;
330	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
331	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
332	    }
333	
334	    function toggleKeyHintVisibility() {
335	      const expanded = DOM.keyHint.classList.toggle('visible');
336	      DOM.helpButton.setAttribute('aria-expanded', expanded);
337	    }
338	
339	    function syncKeyHint() {
340	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
341	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
342	    }
343	
344	    function handleKeyDown(event) {
345	      if (event.key === 'Enter' || event.key === ' ') {
346	        if (!event.repeat) state.shiftHeld = event.shiftKey;
347	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
348	        return;
349	      }
350	
351	      if (event.altKey || event.ctrlKey || event.metaKey) return;
352	
353	      if (event.key in config.keySteps) {
354	        event.preventDefault();
355	        changeColor(config.keySteps[event.key]);
356	      } else if (event.key === 'Home') {
357	        event.preventDefault();
358	        setIndex(0, { haptic: true });
359	      } else if (event.key === 'End') {
360	        event.preventDefault();
361	        setIndex(config.colors.length - 1, { haptic: true });
362	      }
363	    }
364	
365	    function handleEscape(event) {
366	      if (event.key !== 'Escape' || event.defaultPrevented) return;
367	      if (DOM.keyHint.classList.contains('visible')) toggleKeyHintVisibility();
368	    }
369	
370	    // Initialize
371	    syncFromStorage();
372	
373	    // Wait two frames to ensure layout is complete before enabling transitions
374	    requestAnimationFrame(() => requestAnimationFrame(() => {
375	      DOM.button.classList.remove('no-transition');
376	    }));
377	
378	    updateDeviceVerbs();
379	    syncKeyHint();
380	    // e.g. a tablet gaining or losing a trackpad/keyboard
381	    state.hoverQuery.addEventListener('change', () => {
382	      updateDeviceVerbs();
383	      syncKeyHint();
384	    });
385	
386	    // Event listeners
387	    function clearLongPressTimer() {
388	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
389	      state.longPressTimer = null;
390	    }
391	
392	    function attachEventListeners() {
393	      DOM.button.addEventListener('keydown', handleKeyDown);
394	      DOM.button.addEventListener('keyup', (event) => {
395	        if (event.key === ' ') state.shiftHeld = event.shiftKey;
396	      });
397	      DOM.button.addEventListener('blur', () => {
398	        state.shiftHeld = false;
399	        clearLongPressTimer();
400	        clearTimeout(state.clickTimer);
401	      });
402	      DOM.button.addEventListener('pointerdown', (event) => {
403	        clearLongPressTimer();
404	        state.longPressed = false;
405	        state.pointerType = event.pointerType;
406	        if (!event.isPrimary || event.button !== 0) return;
407	        state.pressX = event.clientX;
408	        state.pressY = event.clientY;
409	        state.longPressTimer = setTimeout(() => {
410	          state.longPressTimer = null;
411	          state.longPressed = true;
412	          setIndex(0, { haptic: true, acknowledge: true });
413	        }, config.longPressDuration);
414	      }, { passive: true });
415	      // Touch pointers are captured, so a finger sliding away never fires pointerleave
416	      DOM.button.addEventListener('pointermove', (event) => {
417	        if (!state.longPressTimer) return;
418	        const distance = Math.hypot(event.clientX - state.pressX, event.clientY - state.pressY);
419	        if (distance > config.longPressTolerance) clearLongPressTimer();
420	      }, { passive: true });
421	      DOM.button.addEventListener('contextmenu', (event) => {
422	        if (state.pointerType === 'mouse') {
423	          clearLongPressTimer();
424	        } else if (state.longPressTimer || state.longPressed) {
425	          event.preventDefault();
426	        }
427	      });
428	      DOM.button.addEventListener('pointerup', clearLongPressTimer, { passive: true });
429	      DOM.button.addEventListener('pointercancel', clearLongPressTimer, { passive: true });
430	      DOM.button.addEventListener('pointerleave', clearLongPressTimer, { passive: true });
431	      DOM.button.addEventListener('click', (event) => {
432	        clearLongPressTimer();
433	        const afterLongPress = state.longPressed && event.detail !== 0;
434	        state.longPressed = false;
435	        const reverse = event.shiftKey || state.shiftHeld;
436	        state.shiftHeld = false;
437	        // Only the second click of a run belongs to dblclick; later ones cycle again
438	        if (afterLongPress || event.detail === 2) return;
439	        if (event.detail === 1) {
440	          // Delay so a following dblclick can cancel it, avoiding a flash before the reset
441	          clearTimeout(state.clickTimer);
442	          state.clickTimer = setTimeout(() => changeColor(reverse ? -1 : 1), 250);
443	          return;
444	        }
445	        changeColor(reverse ? -1 : 1);
446	      });
447	      DOM.button.addEventListener('dblclick', (event) => {
448	        // Some engines fire dblclick again on every even click of a run
449	        if (event.detail > 2) return;
450	        clearTimeout(state.clickTimer);
451	        setIndex(0, { haptic: true, acknowledge: true });
452	      });
453	      DOM.button.addEventListener('animationend', () => {
454	        DOM.button.classList.remove('color-changed');
455	      });
456	
457	      DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
458	      addEventListener('keydown', handleEscape);
459	    }
460	
461	    attachEventListeners();
462	
463	    addEventListener('storage', (event) => {
464	      // Sync if changed key matches or if entire storage was cleared (key === null)
465	      if (event.key !== config.storageKey && event.key !== null) return;
466	      syncFromStorage(event.newValue);
467	    });
468	    // Storage events are not delivered while the page sits in the bfcache
469	    addEventListener('pageshow', (event) => {
470	      if (event.persisted) syncFromStorage();
471	    });
472	  </script>
473	</body>
474	</html>
